  vocab=[("suposición", "condición que se da por cierta para calcular una probabilidad"), ("frecuencia relativa", "casos favorables dividido por el total de repeticiones"), ("muestra representativa", "muestra que se parece al grupo completo"), ("independencia", "un resultado no cambia la probabilidad del siguiente"), ("moneda equilibrada", "moneda con igual probabilidad de cara y sello")],
